// features/lifecycle.feature: Rejecting one document sends the whole vendor back
import { expect, expectStatus, test } from "../../fixtures";

test("rejecting one extraction sends the whole vendor back", { tag: "@LIF-02" }, async ({ apiAs, factory }) => {
  // Arrange
  const reviewer = await apiAs("reviewer");
  const { vendor, extractions } = await factory.vendorInReview();

  // Act
  const response = await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
    data: { decision: "reject", note: "Wrong counterparty" },
  });

  // Assert
  const decided = await expectStatus(response, 200);
  expect(decided.status).toBe("rejected");

  const stored = await expectStatus(await reviewer.get(`/api/vendors/${vendor.id}`), 200);
  expect(stored.status).toBe("rejected");

  const audit = await expectStatus<{ items: { action: string }[] }>(
    await reviewer.get(`/api/vendors/${vendor.id}/audit`),
    200,
  );
  const actions = audit.items.map((e) => e.action);
  const extractionRejected = actions.indexOf("extraction.rejected");
  const vendorRejected = actions.indexOf("vendor.rejected");
  expect(extractionRejected, `audit actions: ${actions.join(", ")}`).toBeGreaterThanOrEqual(0);
  expect(vendorRejected, `audit actions: ${actions.join(", ")}`).toBeGreaterThan(extractionRejected);
});
